head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.canDel = 'Y'; // 하나만 삭제 하도록 한다.
scwin.noti_id = ''; // 삭제 키 값
scwin.del_no = 0; // 삭제 하려는 NO. alert 표시를 위해
scwin.gParamObj = new Array(2);
scwin.gDepCd = js_dep_cd;

scwin.gNOTI_SVC_ID;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        $c.cm.PanelToGroupBox(panel_2);
        scwin.setCode();
        scwin.initPage();
        await scwin.search();
        await scwin.setDataSet();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
