 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30309.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Receiver_OnLoadCompleted
 * @description dts_Receiver 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Receiver_OnLoadCompleted = function(rowcount) {
    try {
        txb_receiver_cnt.setValue("총 : " + rowcount + " 건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30309.dts_Receiver_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_PerPage_onselchange2
 * @description cmb Per Page onselchange2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange2 = async function() {
    try {
        const vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
        scwin.pageSize = vPerPage;
        // alert(pageSize);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.cmb_PerPage_onselchange2" });
    }
};

/**
 * @method
 * @name cmb_PerPage_OnSelected
 * @description cmb Per Page On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_OnSelected = function() {

};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = async function(rowcount) {
    try {
        /*
        var vTotalCnt = dts_Grid.NameString(1, "CNT");
        //FillGridHeader2(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page);

        //alert(pageNoCnt +", "+getObjectValue(cmb_PerPage)+", "+vTotalCnt);
        //페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        FillGridHeader(pageNoCnt, getObjectValue(cmb_PerPage), vTotalCnt, panel_page, 743);

         */

        if (dts_Grid.errorMsg) {
            await $c.win.alert("OnLoadCompleted Error => " + dts_Grid.errorMsg);
        } else {
            if (scwin.pageSize !== '0') {
                if (scwin.vCurrPageNo === 0) {
                    scwin.vCurrPageNo = 1;
                    scwin.totalCnt = dts_Grid.getCellData(0, "CNT");
                }
            } else {
                scwin.totalCnt = rowcount;
            }
            // alert(pageNoCnt +", "+pageSize+", "+totalCnt);
            // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
            $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnClick = async function(row, colid) {
    try {
        if (colid === "TITLE") {
            await scwin.readSendSMS(row, colid);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name img_new_onclick
 * @description 「입력」 클릭 이벤트
