};

/**
 * @method
 * @name trs_del_OnFail
 * @description del On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_del_OnFail = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A002", "전송");
        await $c.win.alert(msg);
        await $c.win.alert(trs_del);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.trs_del_OnFail" });
    }
};

/**
 * @method
 * @name trs_del_OnSuccess
 * @description del On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_del_OnSuccess = async function() {
    try {
        //    var msg = getMessageParam("MSG-A001", "전송");
        await scwin.showResult(trs_del.ErrorMsg);
        scwin.resetDelFlag();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.trs_del_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_Grid_oncheckclick
 * @description grd_Grid oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_oncheckclick = async function(col, colid, bCheck) {
    try {
        if (colid === "CHK_FLAG") {
            // alert(col+":"+colid+":"+bCheck);
            await scwin.checkFlagVal(col, colid);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30309.grd_Grid_oncheckclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSendSMS
 * @description read Send SMS 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSendSMS = async function(row, colid) {
    if (colid === "TITLE") {
        scwin.gNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
        // alert(url);
        const sbmOptions = {
            id : "sbm_dts_Master",
            action : "/SmsMgt.do",
            ref : "",
            target : "dts_Master=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        const sbmOptions2 = {
            id : "sbm_dts_Receiver",
            action : "/EmailMgt.do",
            ref : "",
            target : "dts_Receiver=body.content",
            isProcessMsg : false
        };

        const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
        // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) === false) {
        return;
    }
    scwin.vCurrPageNo = 0;

    /*
    var trstkSubmitYn;

    if ( gDepCd == "2220"  || gDepCd == "3220" || gDepCd == "3B10" ) {
    	trstkSubmitYn = "Y";
    } else if ( gDepCd == "ZSYS"  ) {
    	trstkSubmitYn = "A";
    } else {
    	trstkSubmitYn = "N";
    }
     */

    url += "&MDTYPE=2"; // 알림매체타입, SMS= 2
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + "ULDSTF30309.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
