    // 현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    url += "&MDTYPE=2"; // 알림매체타입, SMS= 2
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&PAGENO=" + scwin.vCurrPageNo;
    url += "&PAGESIZE=" + scwin.pageSize;
    url += "&SCREN_ID=" + "ULDSTF30309.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setDataSet
 * @description set Data Set 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setDataSet = async function() {
    const sbmOptions = {
        id : "sbm_dts_delInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_delInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    $c.stf.comboCbDataSet(cmb_PerPage);
};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    const ToDay = $c.ut.cGetToday2();
    edt_EDATE.setValue(ToDay);
    const vSDATE = $c.ut.calcMonth(ToDay, -6);
    edt_SDATE.setValue(vSDATE);
    label_5.hide();
    cmb_SMSGBN.hide();
    if (scwin.gDepCd === '2220' || scwin.gDepCd === '3220' || scwin.gDepCd === '3B10' || scwin.gDepCd === 'ZSYS') {
        label_5.show("");
        cmb_SMSGBN.show("");
    } else {
        cmb_SMSGBN.setValue('1');
    }
};

/**
 * @method
 * @name new
 * @description new 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new = async function() {
    if (scwin.gDepCd === '2220' || scwin.gDepCd === '3220' || scwin.gDepCd === '3B10' || scwin.gDepCd === 'ZSYS') {
        if (cmb_SMSGBN.getValue() === "") {
            await $c.win.alert("메시지 구분을 선택하세요.");
            cmb_SMSGBN.focus();
            return false;
        }
    }
    if (js_svrGubun === 'dr') {
        await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return false;
    }
    let msgGbn;
    msgGbn = cmb_SMSGBN.getValue();
    await $c.frame.CreateDialogFrame("SENDSMS_NEW", "/bizspt/ULDSTF30308.gfm?MSG_GBN=" + msgGbn, "문자보내기", 200, 50, 800, 665 + 30, "window");
};

/**
 * @method
 * @name openNew
 * @description 문자 재발송
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openNew = async function(row) {
    // if ( js_svrGubun == 'dr') {
    //    alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
    //    return;
    // }

    let vNOTI_SVC_ID = '';
    const inAddTyp = 'Y';

    // if (inAddTyp == 'Y') {
    vNOTI_SVC_ID = dts_Grid.getCellData(row, "NOTI_SVC_ID");
    // }

    // alert(vNOTI_SVC_ID);

    let url = "";
    url = "/bizspt/ULDSTF30308.gfm?";
    url += "NOTI_SVC_ID=" + vNOTI_SVC_ID;
    url += "&ADD_INPUT=" + inAddTyp;
    url += "&frameID=" + frame.FrameID;
    if (await scwin.setParam(vNOTI_SVC_ID, inAddTyp)) {
        // formal arguments
        // frame.Provider("../../").GWinOpen("ULDSTF30308", url, "문자 재발송", 200, 10, 790, 750+30,"");
        await $c.frame.CreateDialogFrame("SENDSMS_RESEND", url, "문자 다시보내기", 200, 50, 800, 665 + 30, "window");
    }
};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) === "undefined") {
        await $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) {
        // actual arguments
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name checkFlagVal
 * @description check Flag Val 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkFlagVal = async function(row, colid) {
    chkVal = dts_Grid.getCellData(row, "CHK_FLAG");
    delYN = dts_Grid.getCellData(row, "FLAG");
    empNo = dts_Grid.getCellData(row, "SND_CHRG_EMP_NO");
    depCd = dts_Grid.getCellData(row, "DEP_CD");
    if (scwin.canDelete(empNo, depCd)) {
        if (chkVal === '1') {
            if (delYN === 'Y') {
                if (scwin.canDel === 'Y') {
                    scwin.canDel = 'N';
                    scwin.noti_id = dts_Grid.getCellData(row, "NOTI_SVC_ID");
                    scwin.del_no = row;
                    scwin.setDelData(scwin.noti_id, js_emp_no);
                } else {
                    await $c.win.alert('삭제는 한건씩만 가능 합니다.');
                    dts_Grid.setCellData(row, "CHK_FLAG", 0);
                }
            } else {
                await $c.win.alert('기 삭제, 발송된 건은 삭제 할 수 없습니다.');
                dts_Grid.setCellData(row, "CHK_FLAG", 0);
            }
        } else {
            scwin.resetDelFlag();
        }
    } else {
        dts_Grid.setCellData(row, "CHK_FLAG", 0);
        await $c.win.alert('보낸이거나 보낸이와 같은 팀원만 삭제 가능합니다.');
    }
};

/**
 * @method
 * @name resetDelFlag
 * @description reset Del Flag 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetDelFlag = function() {
    scwin.canDel = 'Y';
    scwin.del_no = 0;
    dts_delInfo.removeAll();
};

/**
 * @method
 * @name canDelete
 * @description KBoY 2017-08-28 당사자이거나 보낸이와 같은 팀인 경우에만 삭제 가능.
 * @param {*} vEmpNo vEmpNo
 * @param {String} vDepCd vDepCd
 * @returns {void}
 * @hidden N
 */
scwin.canDelete = function(vEmpNo, vDepCd) {
    if (vEmpNo === js_emp_no) {
        return true;
    } else {
        if (vDepCd === js_dep_cd) {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name setDelData
 * @description KBoY 2017-08-28 삭제할 목록 ID와 삭제한 EMP_NO를 세팅한다.
 * @param {String} vNotiId vNotiId
 * @param {*} vEmpNo vEmpNo
 * @returns {void}
 * @hidden N
 */
scwin.setDelData = function(vNotiId, vEmpNo) {
    dts_delInfo.insertRow();
    dts_delInfo.setCellData(1, "NOTI_SVC_ID", vNotiId);
    dts_delInfo.setCellData(1, "SND_CHRG_EMP_NO", vEmpNo);
};

/**
 * @method
 * @name doDel
 * @description KBoY 2017-08-28
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doDel = async function() {
    let msg = scwin.del_no + '번을 삭제하시겠습니까?';
    if (await scwin.isChecked()) {
        if (confirm(msg)) {
            scwin.delSMS();
        }
    }
};

/**
 * @method
 * @name isChecked
 * @description is Checked 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isChecked = async function() {
    if (scwin.noti_id === '' || scwin.del_no === 0) {
        await $c.win.alert('삭제할 예약 서비스를 선택하십시오');
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name delSMS
 * @description del SMS 처리
 * @returns {void}
 * @hidden N
 */
scwin.delSMS = function() {
    let url = "/SmsMgt.do?method=deleteSMS" + "&USR_ID=" + js_id + "&SCREN_ID=" + "ULDSTF30309.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    trs_del.Action = url;
    trs_del.KeyName = "toinb_dataid4";
    trs_del.KeyValue = "JSP(I:pInputVal=dts_delInfo)";
    trs_del.post();
};

// S:SDK_SMS_SEND테이블에서 삭제하다가 에러
// N:TBLD_CORP_NOTI_SVC 삭제자 정보 업데이트하려다 에러
// E:SDK_SMS_SEND 삭제 시도할때 에러(그냥 시작하기도전에 에러)

/**
 * @method
 * @name showResult
 * @description show Result 처리
 * @param {*} ver ver
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showResult = async function(ver) {
    if (ver === "S" || ver === "N" || ver === "E") {
        await $c.win.alert('삭제 처리 중 오류가 발생하였습니다. 관리자에게 문의하세요. errorCode :' + ver);
    } else if (ver === "0") {
        await $c.win.alert('기 삭제되었거나, 이미 발송 되었습니다. 관리자에게 문의하세요. errorCode :' + ver);
    } else {
        await $c.win.alert('요청한 삭제 건에 대한 ' + ver + '건의 예약 메세지를 삭제하였습니다.');
    }
};

/**
 * @method
 * @name grd_Grid_CanColumnPosChange
